import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendError(401);
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Validate report type against whitelist
        List<String> validTypes = Arrays.asList("summary", "detailed", "audit");
        if (!validTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Build query - department parameter used for filtering
        String query = buildReportQuery(reportType, dateRange, department, sessionUser);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"value\": \"%s\", \"dept\": \"%s\"}",
                    rs.getInt(1), rs.getString(2), rs.getString(3), rs.getString(4));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String buildReportQuery(String type, String range, String dept, String user) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT r.id, r.name, r.value, r.department FROM reports r ");
        sb.append("WHERE r.report_type = '").append(type).append("' ");
        sb.append("AND r.owner = '").append(user).append("' ");

        if (range != null) {
            String[] parts = range.split("_");
            sb.append("AND r.created_at BETWEEN '").append(parts[0])
              .append("' AND '").append(parts[1]).append("' ");
        }

        if (dept != null && !dept.isEmpty()) {
            sb.append("AND r.department = '").append(dept).append("' ");
        }

        sb.append("ORDER BY r.created_at DESC LIMIT 500");
        return sb.toString();
    }
}
